      ss=tuple(sorted(raw)); terms[ss]=terms.get(ss,0)-(-1)**inv
    for ss,coef in terms.items():
     if coef: D[(ids[k-1][(ff,ss)],c)]=sign*coef
  ds.append(D)
 return cells,ds

